// ===== UNO 共用：牌庫、規則、卡通牌繪製、動畫/音效工具 =====

// 明亮卡通配色（手遊風）
const UNO_COLOR_INFO = {
  R: { name: '紅', hex: '#ff6b6b', dark: '#d64545', light: '#ff8787' },
  Y: { name: '黃', hex: '#ffd43b', dark: '#e6a800', light: '#ffe066' },
  G: { name: '綠', hex: '#51cf66', dark: '#37a848', light: '#8ce99a' },
  B: { name: '藍', hex: '#339af0', dark: '#1971c2', light: '#74c0fc' },
  W: { name: '萬用', hex: '#495057', dark: '#343a40', light: '#868e96' },
};
const UNO_COLORS = ['R', 'Y', 'G', 'B'];

function buildUnoDeck() {
  const deck = [];
  let n = 0;
  for (const c of UNO_COLORS) {
    deck.push({ id: 'c' + (n++), color: c, value: 0 });
    for (let v = 1; v <= 9; v++) {
      deck.push({ id: 'c' + (n++), color: c, value: v });
      deck.push({ id: 'c' + (n++), color: c, value: v });
    }
    for (const a of ['skip', 'reverse', 'draw2']) {
      deck.push({ id: 'c' + (n++), color: c, value: a });
      deck.push({ id: 'c' + (n++), color: c, value: a });
    }
  }
  for (let i = 0; i < 4; i++) {
    deck.push({ id: 'c' + (n++), color: 'W', value: 'wild' });
    deck.push({ id: 'c' + (n++), color: 'W', value: 'wild4' });
  }
  return deck;
}

function unoShuffle(a) {
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}

function unoCardSymbol(card) {
  const v = card.value;
  if (typeof v === 'number') return String(v);
  return { skip: '⊘', reverse: '⇄', draw2: '+2', wild: '★', wild4: '+4' }[v] || '?';
}

function unoCardName(card) {
  const cname = UNO_COLOR_INFO[card.color].name;
  const v = card.value;
  if (typeof v === 'number') return cname + v;
  const names = { skip: '跳過', reverse: '反轉', draw2: '抽二', wild: '萬用', wild4: '萬用抽四' };
  return (card.color === 'W' ? '' : cname) + (names[v] || '?');
}

// top = 棄牌堆頂；currentColor = 目前指定色；hand 用於 wild4 限制（手上無同顏色牌才能出）
function unoCanPlay(card, top, currentColor, hand) {
  if (card.value === 'wild') return true;
  if (card.value === 'wild4') {
    if (!hand) return true;
    return !hand.some(function (c) { return c.color === currentColor; });
  }
  if (card.color === currentColor) return true;
  if (top && card.value === top.value) return true;
  return false;
}

// ---------- 繪圖工具 ----------
function roundRectPath(ctx, x, y, w, h, r) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

// 柔和陰影的圓角矩形（毛玻璃感）
function drawSoftPanel(ctx, x, y, w, h, r, fill, shadow) {
  ctx.save();
  if (shadow) {
    ctx.shadowColor = 'rgba(0,0,0,0.18)';
    ctx.shadowBlur = 24;
    ctx.shadowOffsetY = 8;
  }
  ctx.fillStyle = fill;
  roundRectPath(ctx, x, y, w, h, r);
  ctx.fill();
  ctx.restore();
}

// 畫一張 UNO 牌（卡通手遊風）。opts: { dim, faceDown, chosenColor, glow, lift, scale }
function drawUnoCard(ctx, card, x, y, w, h, opts) {
  opts = opts || {};
  const scale = opts.scale || 1;
  const sw = w * scale, sh = h * scale;
  const dx = x - (sw - w) / 2, dy = y - (sh - h) / 2 - (opts.lift || 0);
  const r = sw * 0.16;

  ctx.save();
  // 浮起陰影
  ctx.shadowColor = 'rgba(0,0,0,0.25)';
  ctx.shadowBlur = 18 * scale;
  ctx.shadowOffsetY = 6 * scale;

  // 牌底：白色帶圓角
  ctx.fillStyle = opts.faceDown ? '#e7f5ff' : '#fffbf0';
  roundRectPath(ctx, dx, dy, sw, sh, r);
  ctx.fill();
  ctx.shadowBlur = 0;
  ctx.shadowOffsetY = 0;

  // 邊框
  ctx.lineWidth = Math.max(2, sw * 0.03);
  ctx.strokeStyle = opts.faceDown ? '#339af0' : 'rgba(0,0,0,0.08)';
  roundRectPath(ctx, dx, dy, sw, sh, r);
  ctx.stroke();

  if (opts.faceDown) {
    // 卡通牌背：藍色橢圓 + UNO 字
    ctx.fillStyle = '#339af0';
    ctx.beginPath();
    ctx.ellipse(dx + sw / 2, dy + sh / 2, sw * 0.38, sh * 0.3, -0.4, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#fff';
    ctx.font = 'bold ' + Math.floor(sw * 0.22) + 'px sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('UNO', dx + sw / 2, dy + sh / 2);
    ctx.restore();
    return;
  }

  const info = UNO_COLOR_INFO[card.color];
  const mainCol = (card.color === 'W' && opts.chosenColor) ? UNO_COLOR_INFO[opts.chosenColor].hex : info.hex;
  const darkCol = (card.color === 'W' && opts.chosenColor) ? UNO_COLOR_INFO[opts.chosenColor].dark : info.dark;

  // 中央大色塊（圓潤橢圓）
  const grad = ctx.createLinearGradient(dx, dy, dx + sw, dy + sh);
  grad.addColorStop(0, mainCol);
  grad.addColorStop(1, darkCol);
  ctx.fillStyle = grad;
  ctx.beginPath();
  ctx.ellipse(dx + sw / 2, dy + sh / 2, sw * 0.42, sh * 0.3, -0.45, 0, Math.PI * 2);
  ctx.fill();

  // 高光
  ctx.fillStyle = 'rgba(255,255,255,0.25)';
  ctx.beginPath();
  ctx.ellipse(dx + sw / 2 - sw * 0.08, dy + sh / 2 - sh * 0.08, sw * 0.2, sh * 0.12, -0.45, 0, Math.PI * 2);
  ctx.fill();

  // 中央符號（白色大字帶陰影）
  const sym = unoCardSymbol(card);
  ctx.save();
  ctx.shadowColor = 'rgba(0,0,0,0.2)';
  ctx.shadowBlur = 4;
  ctx.shadowOffsetY = 2;
  ctx.fillStyle = '#fff';
  ctx.font = 'bold ' + Math.floor(sw * 0.44) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(sym, dx + sw / 2, dy + sh / 2 + 1);
  ctx.restore();

  // 角落小符號（圓形底）
  const cornerCol = card.color === 'W' ? '#343a40' : info.hex;
  ctx.fillStyle = cornerCol;
  ctx.beginPath();
  ctx.arc(dx + sw * 0.14, dy + sh * 0.1, sw * 0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.font = 'bold ' + Math.floor(sw * 0.14) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(sym, dx + sw * 0.14, dy + sh * 0.1 + 1);

  ctx.save();
  ctx.translate(dx + sw * 0.86, dy + sh * 0.9);
  ctx.rotate(Math.PI);
  ctx.fillStyle = cornerCol;
  ctx.beginPath();
  ctx.arc(0, 0, sw * 0.1, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.font = 'bold ' + Math.floor(sw * 0.14) + 'px sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(sym, 0, 1);
  ctx.restore();

  // 萬用牌四色角標
  if (card.color === 'W') {
    const s = sw * 0.16;
    for (let i = 0; i < 4; i++) {
      ctx.fillStyle = UNO_COLOR_INFO[UNO_COLORS[i]].hex;
      roundRectPath(ctx, dx + sw * 0.5 - s + (i % 2) * s * 1.05, dy + sh * 0.82 + Math.floor(i / 2) * s * 0.6, s * 0.95, s * 0.5, s * 0.12);
      ctx.fill();
    }
  }

  if (opts.dim) {
    ctx.fillStyle = 'rgba(255,255,255,0.55)';
    roundRectPath(ctx, dx, dy, sw, sh, r);
    ctx.fill();
  }

  if (opts.glow) {
    ctx.save();
    ctx.shadowColor = UNO_COLOR_INFO.Y.light;
    ctx.shadowBlur = 30;
    ctx.lineWidth = 3;
    ctx.strokeStyle = UNO_COLOR_INFO.Y.light;
    roundRectPath(ctx, dx - 2, dy - 2, sw + 4, sh + 4, r + 2);
    ctx.stroke();
    ctx.restore();
  }

  ctx.restore();
}

// ---------- 動畫工具 ----------
const UAnim = {
  // easeOutBack：可愛的彈跳感
  easeOutBack: function (t) {
    const c1 = 1.70158, c3 = c1 + 1;
    return 1 + c3 * Math.pow(t - 1, 3) + c1 * Math.pow(t - 1, 2);
  },
  easeOutCubic: function (t) { return 1 - Math.pow(1 - t, 3); },
  easeInOutQuad: function (t) { return t < 0.5 ? 2 * t * t : 1 - Math.pow(-2 * t + 2, 2) / 2; },
};

// 飛行卡片動畫
function UFlyingCard(card, fromX, fromY, toX, toY, dur, opts) {
  opts = opts || {};
  return {
    card: card,
    fromX: fromX, fromY: fromY,
    toX: toX, toY: toY,
    start: performance.now(),
    dur: dur || 400,
    rot: opts.rot || (Math.random() - 0.5) * 0.3,
    scale: opts.scale || 1,
    onDone: opts.onDone || null,
    dead: false,
  };
}

function UAnimUpdateFly(fly, now) {
  const t = Math.min(1, (now - fly.start) / fly.dur);
  const e = UAnim.easeOutCubic(t);
  fly.x = fly.fromX + (fly.toX - fly.fromX) * e;
  fly.y = fly.fromY + (fly.toY - fly.fromY) * e + Math.sin(t * Math.PI) * -30; // 微拋物線
  fly.rotNow = fly.rot * (1 - t);
  fly.scaleNow = 0.6 + 0.4 * UAnim.easeOutBack(Math.min(1, t * 1.2));
  if (t >= 1 && !fly.dead) {
    fly.dead = true;
    if (fly.onDone) fly.onDone();
  }
  return t < 1;
}

// ---------- WebAudio 音效（手機需在 user gesture 後 init） ----------
const USound = {
  ctx: null,
  init: function () {
    if (!this.ctx) this.ctx = new (window.AudioContext || window.webkitAudioContext)();
  },
  play: function (freq, dur, type, vol) {
    if (!this.ctx) return;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type || 'sine';
    o.frequency.value = freq;
    g.gain.setValueAtTime(vol || 0.15, this.ctx.currentTime);
    g.gain.exponentialRampToValueAtTime(0.01, this.ctx.currentTime + dur);
    o.connect(g).connect(this.ctx.destination);
    o.start();
    o.stop(this.ctx.currentTime + dur);
  },
  card: function () { this.play(600, 0.08, 'triangle', 0.2); },
  draw: function () { this.play(300, 0.12, 'sine', 0.15); },
  uno: function () { this.play(800, 0.1, 'square', 0.15); setTimeout(() => this.play(1000, 0.15, 'square', 0.15), 80); },
  win: function () {
    [523, 659, 784, 1047].forEach((f, i) => setTimeout(() => this.play(f, 0.2, 'triangle', 0.2), i * 100));
  },
  error: function () { this.play(200, 0.2, 'sawtooth', 0.12); },
};

// ===== UNO 大螢幕：權威遊戲邏輯（狀態機 + 收發訊息） =====
try { GameAPI.log('DKEYS:' + Object.keys(GameAPI).join(',')); } catch (e) {}
// 手機只送意圖事件（play/draw/pass/uno/color），這裡驗證並廣播完整狀態。
const UCFG = GameAPI.config || GameAPI.fieldConfig || {};
const U = {
  started: false,
  order: [],            // [pid] 座位順序
  names: {},            // pid -> 名稱
  colors: {},           // pid -> 顏色
  hands: {},            // pid -> [card]
  deck: [],
  discard: [],
  currentColor: 'R',
  direction: 1,
  seat: 0,
  phase: 'playing',     // playing | colorPick | drawn | drawwait | over
  drawnId: null,
  wildPending: null,
  unoArmed: {},         // pid -> true（本回合預先按了 UNO）
  unoWindow: null,      // { pid, until } 剩 1 張未喊 UNO 的 3 秒窗口
  winner: null,
  scores: {},           // pid -> 累計勝場（跨局保留）
  round: 1,             // 第幾局
  rematchAt: 0,         // 勝利後自動開下一局的時間點（0 = 無排程）
  log: [],
  turnDeadline: 0,
  autoAt: 0,
  lastBc: 0,
  fx: [],            // 動畫效果佇列（render 端消費）
  handSize: Math.max(1, Math.min(10, UCFG.handSize || 7)),
  turnMs: Math.max(10, Math.min(120, UCFG.turnSeconds || 45)) * 1000,
};

function uNow() { return performance.now(); }
function uName(pid) { return U.names[pid] || '玩家'; }
function uCur() { return U.order[U.seat]; }
function uPeek(steps) {
  const n = U.order.length;
  return ((U.seat + U.direction * steps) % n + n) % n;
}
function uLog(msg) {
  U.log.push(msg);
  if (U.log.length > 30) U.log.shift();
}

// 觸發畫面效果（render 端每幀消費）
function uFx(type, data) {
  U.fx.push({ type: type, data: data || {}, at: uNow() });
}

function uStart() {
  GameAPI.players.forEach(function (p, pid) {
    U.order.push(pid);
    U.names[pid] = p.name || '玩家';
    U.colors[pid] = p.color || '#ffffff';
  });
  if (U.order.length < 2) {
    GameAPI.log('UNO: 玩家不足，等待中');
    return; // render 會顯示等待畫面
  }
  const top = uDeal();
  U.started = true;
  uLog('遊戲開始！起始牌：' + unoCardName(top));
  uNewTurn();
  uBroadcast();
}

// 發一局牌：洗牌、發手牌、翻起始牌（翻到數字牌為止，功能牌塞回牌庫底）。回傳起始牌。
function uDeal() {
  U.deck = unoShuffle(buildUnoDeck());
  U.hands = {};
  U.direction = 1;
  U.order.forEach(function (pid) { U.hands[pid] = []; });
  for (let r = 0; r < U.handSize; r++) {
    for (const pid of U.order) U.hands[pid].push(U.deck.pop());
  }
  let top = U.deck.pop();
  while (typeof top.value !== 'number') {
    U.deck.unshift(top);
    top = U.deck.pop();
  }
  U.discard = [top];
  U.currentColor = top.color;
  return top;
}

// 再來一局：重建座位（納入中途加入的玩家）、保留累計勝場，上局贏家先手
function uRestart() {
  const lastWinner = U.winner;
  U.order = [];
  GameAPI.players.forEach(function (p, pid) {
    U.order.push(pid);
    U.names[pid] = p.name || '玩家';
    U.colors[pid] = p.color || '#ffffff';
  });
  if (U.order.length < 2) { U.rematchAt = uNow() + 5000; return; } // 人不夠，再等 5 秒
  U.round++;
  const wi = U.order.indexOf(lastWinner);
  U.seat = wi >= 0 ? wi : 0;
  U.winner = null;
  U.rematchAt = 0;
  U.unoWindow = null;   // 上一局結束瞬間可能還開著別人的 UNO 窗口，不清會在新局誤罰
  const top = uDeal();
  uLog('🔄 第 ' + U.round + ' 局開始！起始牌：' + unoCardName(top));
  uFx('newRound', { round: U.round });
  uNewTurn();
  uReportScores();   // 新局開始再補送一次(斷線自癒的最後保險)
  uBroadcast();
}

function uNewTurn() {
  U.phase = 'playing';
  U.drawnId = null;
  U.wildPending = null;
  U.unoArmed = {};
  U.turnDeadline = uNow() + U.turnMs;
}

function uDrawCards(pid, n) {
  const hand = U.hands[pid];
  for (let i = 0; i < n; i++) {
    if (U.deck.length === 0) {
      // 棄牌堆（保留頂牌）洗回牌庫
      const top = U.discard.pop();
      U.deck = unoShuffle(U.discard);
      U.discard = [top];
      if (U.deck.length === 0) return; // 極端情況：無牌可抽
      uLog('牌庫重洗！');
    }
    hand.push(U.deck.pop());
  }
}

// 結算打出的牌（顏色已確定），套用效果並換人
function uResolveCard(card, chosenColor) {
  const v = card.value;
  if (card.color === 'W') U.currentColor = chosenColor;
  else U.currentColor = card.color;
  let steps = 1;
  if (v === 'reverse') {
    U.direction *= -1;
    uLog('方向反轉！');
    if (U.order.length === 2) steps = 2; // 兩人局反轉 = 跳過
  } else if (v === 'skip') {
    steps = 2;
    uLog(uName(U.order[uPeek(1)]) + ' 被跳過！');
  } else if (v === 'draw2') {
    const t = U.order[uPeek(1)];
    uDrawCards(t, 2);
    steps = 2;
    uLog(uName(t) + ' 抽 2 張並跳過！');
    uFx('draw2', { pid: t });
  } else if (v === 'wild4') {
    const t = U.order[uPeek(1)];
    uDrawCards(t, 4);
    steps = 2;
    uLog(uName(t) + ' 抽 4 張並跳過！');
    uFx('wild4', { pid: t });
  }
  if (card.color === 'W' && chosenColor) {
    uLog('顏色指定為 ' + UNO_COLOR_INFO[chosenColor].name);
    uFx('color', { color: chosenColor });
  }
  U.seat = uPeek(steps);
  uNewTurn();
}

function uPlay(pid, cardId, color) {
  if (!U.started || (U.phase !== 'playing' && U.phase !== 'drawn')) return;
  if (uCur() !== pid) return;
  const hand = U.hands[pid];
  const ci = hand.findIndex(function (c) { return c.id === cardId; });
  if (ci < 0) return;
  const card = hand[ci];
  if (U.phase === 'drawn' && card.id !== U.drawnId) return; // 抽牌後只能出抽到的牌或跳過
  const top = U.discard[U.discard.length - 1];
  if (!unoCanPlay(card, top, U.currentColor, hand)) return;
  hand.splice(ci, 1);
  U.discard.push(card);
  uLog(uName(pid) + ' 打出 ' + unoCardName(card));
  uFx('play', { pid: pid, card: card });
  if (typeof card.value !== 'number') uFx('action', { value: card.value });
  // UNO 判定
  if (hand.length === 1) {
    if (U.unoArmed[pid]) {
      uLog(uName(pid) + ' 喊了 UNO！');
    } else {
      U.unoWindow = { pid: pid, until: uNow() + 3000 };
      uFx('unoWarn', { pid: pid });
    }
  }
  U.unoArmed[pid] = false;
  if (hand.length === 0) { uWin(pid); uBroadcast(); return; }
  if (card.color === 'W') {
    if (color && UNO_COLOR_INFO[color] && color !== 'W') {
      uResolveCard(card, color);
    } else {
      U.phase = 'colorPick'; // 等玩家選色（含超時隨機）
      U.wildPending = card;
    }
    uBroadcast();
    return;
  }
  uResolveCard(card, null);
  uBroadcast();
}

function uPickColor(pid, color) {
  if (U.phase !== 'colorPick' || uCur() !== pid) return;
  if (!UNO_COLOR_INFO[color] || color === 'W') return;
  uResolveCard(U.wildPending, color);
  uBroadcast();
}

function uDraw(pid) {
  if (U.phase !== 'playing' || uCur() !== pid) return;
  const before = U.hands[pid].length;
  uDrawCards(pid, 1);
  if (U.hands[pid].length === before) { // 無牌可抽，直接換人
    U.seat = uPeek(1);
    uNewTurn();
    uBroadcast();
    return;
  }
  const card = U.hands[pid][U.hands[pid].length - 1];
  uLog(uName(pid) + ' 抽了一張牌');
  uFx('draw', { pid: pid });
  const top = U.discard[U.discard.length - 1];
  if (unoCanPlay(card, top, U.currentColor, U.hands[pid])) {
    U.phase = 'drawn';
    U.drawnId = card.id;
  } else {
    U.phase = 'drawwait'; // 讓玩家看到抽了什麼，1.5 秒後自動換人
    U.autoAt = uNow() + 1500;
  }
  uBroadcast();
}

function uPass(pid) {
  if (U.phase !== 'drawn' || uCur() !== pid) return;
  uLog(uName(pid) + ' 跳過');
  U.seat = uPeek(1);
  uNewTurn();
  uBroadcast();
}

function uUno(pid) {
  if (!U.started || U.phase === 'over') return;
  if (U.unoWindow && U.unoWindow.pid === pid) {
    U.unoWindow = null;
    uLog(uName(pid) + ' 喊了 UNO！');
  } else if (uCur() === pid) {
    U.unoArmed[pid] = true;
  }
  uBroadcast();
}

function uWin(pid) {
  U.phase = 'over';
  U.winner = pid;
  U.scores[pid] = (U.scores[pid] || 0) + 1;
  U.rematchAt = uNow() + 10000;   // 10 秒後自動開下一局（主持人隨時可推進到結果結束整場）
  uLog('🎉 ' + uName(pid) + ' 出完手牌，獲勝！（累計 ' + U.scores[pid] + ' 勝）');
  uFx('win', { pid: pid });
  uReportScores();
}

// 把累計勝場寫回框架：display broadcast 的保留事件 { t:'score' } 會被轉發層
// （GameSession.applyReservedGameEvent）攔截寫進 player.score → result 階段依此排名；
// { t:'set_attr' } 同步寫 playerAttribute score（跨階段可讀，非排名依據）。只有 display 端有效。
function uReportScores() {
  U.order.forEach(function (pid) {
    const wins = U.scores[pid] || 0;
    if (wins <= 0) return;
    GameAPI.broadcast({ t: 'score', pid: pid, score: wins });
    GameAPI.broadcast({ t: 'set_attr', pid: pid, attrId: 'score', value: wins });
  });
}

// 每幀由 render 端呼叫：處理超時與 UNO 懲罰、定期心跳廣播（讓晚加入的手機拿到狀態）
function uTick() {
  if (!U.started) return;
  const now = uNow();
  if (now - U.lastBc > 1000) uBroadcast();
  if (U.phase === 'over') {
    // over 期間每秒重送累計勝場(絕對值,冪等):display socket 瞬斷時,斷線中發的事件會在
    // 重連後、join_display 重新註冊「之前」被伺服器丟棄 — 只在 uWin 發一次會整局消失。
    if (now - (U.lastReport || 0) > 1000) { U.lastReport = now; uReportScores(); }
    if (U.rematchAt && now > U.rematchAt) uRestart();
    return;
  }
  if (U.unoWindow && now > U.unoWindow.until) {
    const pid = U.unoWindow.pid;
    U.unoWindow = null;
    uDrawCards(pid, 2);
    uLog(uName(pid) + ' 沒喊 UNO，罰抽 2 張！');
    uFx('penalty', { pid: pid });
    uBroadcast();
  }
  if (U.phase === 'drawwait' && now > U.autoAt) {
    U.seat = uPeek(1);
    uNewTurn();
    uBroadcast();
    return;
  }
  if (now > U.turnDeadline) {
    const pid = uCur();
    if (U.phase === 'colorPick') {
      const rc = UNO_COLORS[Math.floor(Math.random() * 4)];
      uLog(uName(pid) + ' 超時，隨機選色');
      uResolveCard(U.wildPending, rc);
      uBroadcast();
    } else if (U.phase === 'drawn') {
      uLog(uName(pid) + ' 超時自動跳過');
      U.seat = uPeek(1);
      uNewTurn();
      uBroadcast();
    } else if (U.phase === 'playing') {
      uDrawCards(pid, 1);
      uLog(uName(pid) + ' 超時自動抽牌');
      U.seat = uPeek(1);
      uNewTurn();
      uBroadcast();
    }
  }
}

function uBroadcast() {
  U.lastBc = uNow();
  const orderInfo = U.order.map(function (pid) {
    return { pid: pid, name: U.names[pid], count: U.hands[pid] ? U.hands[pid].length : 0 };
  });
  GameAPI.broadcast({
    t: 'state',
    phase: U.phase,
    top: U.discard[U.discard.length - 1] || null,
    color: U.currentColor,
    dir: U.direction,
    cur: U.order.length ? uCur() : null,
    order: orderInfo,
    hands: U.hands,
    drawnId: U.drawnId,
    unoWindow: U.unoWindow,
    winner: U.winner,
    scores: U.scores,
    round: U.round,
    rematchLeftMs: (U.phase === 'over' && U.rematchAt) ? Math.max(0, U.rematchAt - uNow()) : null,
    log: U.log.slice(-6),
    deckCount: U.deck.length,
    turnLeftMs: Math.max(0, U.turnDeadline - uNow()),
    turnMs: U.turnMs,
  });
}

// 收手機事件
GameAPI.onPlayerState(function (pid, msg) {
  if (!msg || typeof msg !== 'object') return;
  if (msg.t === 'hello') uBroadcast();
  else if (msg.t === 'play') uPlay(pid, msg.cardId, msg.color);
  else if (msg.t === 'draw') uDraw(pid);
  else if (msg.t === 'pass') uPass(pid);
  else if (msg.t === 'uno') uUno(pid);
  else if (msg.t === 'color') uPickColor(pid, msg.color);
});

uStart();

// ===== UNO 大螢幕：明亮卡通風渲染（1920×1080） =====
const UW = GameAPI.width, UH = GameAPI.height;
const uctx = GameAPI.ctx;

// ---------- 視覺主題 ----------
const THEME = {
  bgTop: '#e7f5ff', bgBottom: '#fff9db',
  table: '#fffbf0', tableEdge: '#ffe8cc',
  panel: 'rgba(255,255,255,0.75)',
  panelDark: 'rgba(255,255,255,0.5)',
  text: '#343a40',
  textLight: '#868e96',
  accent: '#ffd43b',
};

// 座位位置（環繞中央牌桌）
function uSeatPos(i, n) {
  const a = -Math.PI / 2 + (i / n) * Math.PI * 2;
  return {
    x: UW / 2 + Math.cos(a) * 620,
    y: UH / 2 + 20 + Math.sin(a) * 380,
    ang: a,
  };
}

// 效果狀態
const uFxState = {
  flies: [],          // 飛行卡片
  bigText: null,      // 大字快閃 { text, color, at, dur }
  confetti: [],       // 彩帶
  colorFlash: 0,      // 顏色切換光暈
};

// 消費 logic 端來的效果事件
function uConsumeFx() {
  const now = uNow();
  U.fx = U.fx.filter(function (f) {
    const age = now - f.at;
    if (age > 5000) return false;

    if (f.type === 'play' && !f.consumed) {
      f.consumed = true;
      // 找到出牌者座位
      const idx = U.order.indexOf(f.data.pid);
      const from = idx >= 0 ? uSeatPos(idx, U.order.length) : { x: UW / 2, y: UH / 2 };
      uFxState.flies.push(UFlyingCard(
        f.data.card, from.x, from.y - 60,
        UW / 2 + 70, UH / 2 - 60,
        350, { rot: (Math.random() - 0.5) * 0.4 }
      ));
    }
    if (f.type === 'action' && !f.consumed) {
      f.consumed = true;
      const v = f.data.value;
      const map = {
        skip: { text: '跳過！', color: '#ff8787' },
        reverse: { text: '反轉 ⟲', color: '#74c0fc' },
        draw2: { text: '+2', color: '#ffa94d' },
        wild: { text: '萬用 ★', color: '#b197fc' },
        wild4: { text: '+4 🔥', color: '#ff6b6b' },
      };
      if (map[v]) {
        uFxState.bigText = { text: map[v].text, color: map[v].color, at: now, dur: 900 };
      }
    }
    if (f.type === 'color' && !f.consumed) {
      f.consumed = true;
      uFxState.colorFlash = now;
    }
    if (f.type === 'win' && !f.consumed) {
      f.consumed = true;
      for (let i = 0; i < 60; i++) {
        uFxState.confetti.push({
          x: UW / 2 + (Math.random() - 0.5) * 400,
          y: UH / 2 - 100,
          vx: (Math.random() - 0.5) * 8,
          vy: -Math.random() * 6 - 2,
          color: ['#ff6b6b', '#ffd43b', '#51cf66', '#339af0', '#b197fc'][i % 5],
          rot: Math.random() * Math.PI * 2,
          vr: (Math.random() - 0.5) * 0.2,
          size: 8 + Math.random() * 8,
          at: now,
        });
      }
    }
    if (f.type === 'unoWarn' && !f.consumed) {
      f.consumed = true;
      uFxState.bigText = { text: 'UNO！', color: '#ff6b6b', at: now, dur: 600 };
    }
    return true;
  });
}

function uRender(ts) {
  uConsumeFx();
  const now = uNow();

  // ===== 背景：柔和漸層 =====
  const g = uctx.createLinearGradient(0, 0, 0, UH);
  g.addColorStop(0, THEME.bgTop);
  g.addColorStop(1, THEME.bgBottom);
  uctx.fillStyle = g;
  uctx.fillRect(0, 0, UW, UH);

  // 裝飾圓圈
  uctx.fillStyle = 'rgba(255,255,255,0.4)';
  for (let i = 0; i < 6; i++) {
    const a = ts / 3000 + i * Math.PI / 3;
    const r = 200 + i * 80;
    uctx.beginPath();
    uctx.arc(UW / 2 + Math.cos(a) * 300, UH / 2 + Math.sin(a) * 200, r, 0, Math.PI * 2);
    uctx.fill();
  }

  if (!U.started) {
    uctx.fillStyle = THEME.text;
    uctx.font = 'bold 96px sans-serif';
    uctx.textAlign = 'center';
    uctx.textBaseline = 'middle';
    uctx.fillText('UNO', UW / 2, UH / 2 - 80);
    uctx.font = '42px sans-serif';
    uctx.fillStyle = THEME.textLight;
    uctx.fillText('等待玩家加入…（至少 2 人）', UW / 2, UH / 2 + 40);
    return;
  }

  const top = U.discard[U.discard.length - 1];

  // ===== 中央牌桌面板 =====
  drawSoftPanel(uctx, UW / 2 - 340, UH / 2 - 260, 680, 560, 48, THEME.table, true);
  uctx.strokeStyle = THEME.tableEdge;
  uctx.lineWidth = 6;
  roundRectPath(uctx, UW / 2 - 340, UH / 2 - 260, 680, 560, 48);
  uctx.stroke();

  // 顏色切換光暈
  if (uFxState.colorFlash && now - uFxState.colorFlash < 500) {
    const ft = (now - uFxState.colorFlash) / 500;
    const c = UNO_COLOR_INFO[U.currentColor];
    uctx.save();
    uctx.globalAlpha = 0.3 * (1 - ft);
    uctx.fillStyle = c.hex;
    uctx.beginPath();
    uctx.arc(UW / 2, UH / 2 + 20, 300 * UAnim.easeOutCubic(ft), 0, Math.PI * 2);
    uctx.fill();
    uctx.restore();
  }

  // ===== 玩家座位 =====
  const n = U.order.length;
  for (let i = 0; i < n; i++) {
    const pid = U.order[i];
    const pos = uSeatPos(i, n);
    const isCur = i === U.seat && U.phase !== 'over';
    const count = U.hands[pid].length;
    const name = uName(pid);

    // 呼吸發光
    let glow = 0;
    if (isCur) glow = 0.5 + 0.5 * Math.sin(ts / 400);

    // 面板
    const pw = 280, ph = 120;
    drawSoftPanel(uctx, pos.x - pw / 2, pos.y - ph / 2, pw, ph,
      32, isCur ? 'rgba(255,255,255,0.95)' : THEME.panel, true);

    // 當前玩家邊框
    if (isCur) {
      uctx.save();
      uctx.strokeStyle = 'rgba(255,212,59,' + (0.6 + 0.4 * glow) + ')';
      uctx.lineWidth = 5;
      roundRectPath(uctx, pos.x - pw / 2 - 3, pos.y - ph / 2 - 3, pw + 6, ph + 6, 35);
      uctx.stroke();
      uctx.restore();
    }

    // 玩家色點
    uctx.fillStyle = U.colors[pid] || '#adb5bd';
    uctx.beginPath();
    uctx.arc(pos.x - pw / 2 + 36, pos.y - 20, 16, 0, Math.PI * 2);
    uctx.fill();
    uctx.lineWidth = 3;
    uctx.strokeStyle = '#fff';
    uctx.stroke();

    // 名字
    uctx.fillStyle = THEME.text;
    uctx.font = 'bold 34px sans-serif';
    uctx.textAlign = 'left';
    uctx.textBaseline = 'middle';
    uctx.fillText(name.length > 6 ? name.slice(0, 6) + '…' : name, pos.x - pw / 2 + 62, pos.y - 18);

    // 累計勝場（右上角小徽章）
    const wins = U.scores[pid] || 0;
    if (wins > 0) {
      uctx.fillStyle = '#ffd43b';
      uctx.beginPath();
      uctx.arc(pos.x + pw / 2 - 30, pos.y - ph / 2 + 24, 20, 0, Math.PI * 2);
      uctx.fill();
      uctx.lineWidth = 2;
      uctx.strokeStyle = '#fff';
      uctx.stroke();
      uctx.fillStyle = '#fff';
      uctx.font = 'bold 24px sans-serif';
      uctx.textAlign = 'center';
      uctx.fillText(wins, pos.x + pw / 2 - 30, pos.y - ph / 2 + 26);
    }

    // 手牌數（小牌背 + 數字）
    drawUnoCard(uctx, null, pos.x - pw / 2 + 30, pos.y + 12, 48, 64, { faceDown: true, scale: 0.9 });
    uctx.fillStyle = count === 1 ? '#e8590c' : THEME.text;
    uctx.font = 'bold 40px sans-serif';
    uctx.textAlign = 'left';
    uctx.fillText('× ' + count, pos.x - pw / 2 + 86, pos.y + 44);

    // UNO 標記
    if (count === 1 && U.phase !== 'over') {
      const pulse = 0.8 + 0.2 * Math.sin(ts / 200);
      uctx.save();
      uctx.translate(pos.x + pw / 2 - 70, pos.y + 30);
      uctx.scale(pulse, pulse);
      uctx.fillStyle = '#ff6b6b';
      roundRectPath(uctx, -50, -24, 100, 48, 16);
      uctx.fill();
      uctx.fillStyle = '#fff';
      uctx.font = 'bold 28px sans-serif';
      uctx.textAlign = 'center';
      uctx.fillText('UNO!', 0, 2);
      uctx.restore();
    }
  }

  // ===== 中央：牌庫 + 棄牌堆 =====
  // 牌庫（帶數字）
  drawUnoCard(uctx, null, UW / 2 - 220, UH / 2 - 140, 160, 224, { faceDown: true });
  uctx.fillStyle = THEME.textLight;
  uctx.font = 'bold 32px sans-serif';
  uctx.textAlign = 'center';
  uctx.textBaseline = 'top';
  uctx.fillText('牌庫 ' + U.deck.length, UW / 2 - 140, UH / 2 + 96);

  // 棄牌堆頂
  if (top) {
    drawUnoCard(uctx, top, UW / 2 + 60, UH / 2 - 140, 160, 224, {
      chosenColor: top.color === 'W' ? U.currentColor : null,
    });
  }

  // 目前顏色大圓標
  const ci = UNO_COLOR_INFO[U.currentColor];
  uctx.save();
  uctx.shadowColor = ci.hex;
  uctx.shadowBlur = 20;
  uctx.fillStyle = ci.hex;
  uctx.beginPath();
  uctx.arc(UW / 2 + 140, UH / 2 - 200, 36, 0, Math.PI * 2);
  uctx.fill();
  uctx.restore();
  uctx.lineWidth = 4;
  uctx.strokeStyle = '#fff';
  uctx.stroke();
  uctx.fillStyle = '#fff';
  uctx.font = 'bold 26px sans-serif';
  uctx.textAlign = 'center';
  uctx.textBaseline = 'middle';
  uctx.fillText(ci.name, UW / 2 + 140, UH / 2 - 200);

  // 方向指示（旋轉動畫）
  const dirAngle = (ts / 2000) * Math.PI * 2 * U.direction;
  uctx.save();
  uctx.translate(UW / 2, UH / 2 - 200);
  uctx.rotate(dirAngle);
  uctx.fillStyle = THEME.textLight;
  uctx.font = '48px sans-serif';
  uctx.textAlign = 'center';
  uctx.textBaseline = 'middle';
  uctx.fillText('⟳', 0, 0);
  uctx.restore();

  // ===== 回合資訊 =====
  if (U.phase !== 'over') {
    // 倒數條（藥丸形）
    const frac = Math.max(0, Math.min(1, (U.turnDeadline - now) / U.turnMs));
    const barW = 400, barH = 24;
    const barX = UW / 2 - barW / 2, barY = UH / 2 + 160;

    uctx.fillStyle = 'rgba(0,0,0,0.08)';
    roundRectPath(uctx, barX, barY, barW, barH, barH / 2);
    uctx.fill();

    const barColor = frac > 0.3 ? '#51cf66' : '#ff6b6b';
    uctx.fillStyle = barColor;
    roundRectPath(uctx, barX, barY, barW * frac, barH, barH / 2);
    uctx.fill();

    // 輪到誰
    uctx.fillStyle = THEME.text;
    uctx.font = 'bold 36px sans-serif';
    uctx.textAlign = 'center';
    uctx.textBaseline = 'top';
    uctx.fillText('輪到 ' + uName(uCur()), UW / 2, barY + 40);

    if (U.phase === 'colorPick') {
      uctx.fillStyle = '#e8590c';
      uctx.font = 'bold 32px sans-serif';
      uctx.fillText('正在選擇顏色…', UW / 2, barY + 90);
    }
    if (U.unoWindow) {
      const p = 0.7 + 0.3 * Math.sin(ts / 150);
      uctx.fillStyle = 'rgba(230,57,70,' + p + ')';
      uctx.font = 'bold 32px sans-serif';
      uctx.fillText(uName(U.unoWindow.pid) + ' 剩 1 張還沒喊 UNO！', UW / 2, barY + 90);
    }
  }

  // ===== 飛行卡片動畫 =====
  uFxState.flies = uFxState.flies.filter(function (f) {
    const alive = UAnimUpdateFly(f, now);
    if (!f.dead) {
      uctx.save();
      uctx.translate(f.x, f.y);
      uctx.rotate(f.rotNow);
      drawUnoCard(uctx, f.card, -70 * f.scaleNow, -98 * f.scaleNow, 140 * f.scaleNow, 196 * f.scaleNow, {
        chosenColor: f.card.color === 'W' ? U.currentColor : null,
      });
      uctx.restore();
    }
    return alive;
  });

  // ===== 大字快閃 =====
  if (uFxState.bigText && now - uFxState.bigText.at < uFxState.bigText.dur) {
    const bt = uFxState.bigText;
    const age = now - bt.at;
    const t = age / bt.dur;
    const scale = UAnim.easeOutBack(Math.min(1, t * 2));
    const alpha = t > 0.7 ? 1 - (t - 0.7) / 0.3 : 1;

    uctx.save();
    uctx.translate(UW / 2, UH / 2 - 40);
    uctx.scale(scale, scale);
    uctx.globalAlpha = alpha;
    uctx.fillStyle = bt.color;
    uctx.font = 'bold 120px sans-serif';
    uctx.textAlign = 'center';
    uctx.textBaseline = 'middle';
    uctx.shadowColor = 'rgba(0,0,0,0.2)';
    uctx.shadowBlur = 20;
    uctx.fillText(bt.text, 0, 0);
    uctx.restore();
  } else if (uFxState.bigText) {
    uFxState.bigText = null;
  }

  // ===== 行動紀錄（左下，毛玻璃面板） =====
  drawSoftPanel(uctx, 40, UH - 280, 520, 240, 24, THEME.panel, false);
  uctx.fillStyle = THEME.text;
  uctx.font = 'bold 24px sans-serif';
  uctx.textAlign = 'left';
  uctx.textBaseline = 'top';
  uctx.fillText('📋 行動紀錄', 64, UH - 256);

  const logs = U.log.slice(-5);
  uctx.font = '26px sans-serif';
  for (let i = 0; i < logs.length; i++) {
    uctx.fillStyle = i === logs.length - 1 ? '#e8590c' : THEME.textLight;
    uctx.fillText(logs[i], 64, UH - 210 + i * 38);
  }

  // ===== 標題 =====
  uctx.fillStyle = THEME.text;
  uctx.font = 'bold 56px sans-serif';
  uctx.textAlign = 'center';
  uctx.textBaseline = 'middle';
  uctx.fillText('UNO', UW / 2, 70);

  // ===== 彩帶 =====
  if (uFxState.confetti.length) {
    uFxState.confetti = uFxState.confetti.filter(function (c) {
      const age = now - c.at;
      if (age > 3000) return false;
      c.x += c.vx;
      c.y += c.vy;
      c.vy += 0.15;
      c.rot += c.vr;
      const alpha = age > 2000 ? 1 - (age - 2000) / 1000 : 1;
      uctx.save();
      uctx.translate(c.x, c.y);
      uctx.rotate(c.rot);
      uctx.globalAlpha = alpha;
      uctx.fillStyle = c.color;
      uctx.fillRect(-c.size / 2, -c.size / 4, c.size, c.size / 2);
      uctx.restore();
      return true;
    });
  }

  // ===== 勝利畫面 =====
  if (U.phase === 'over') {
    uctx.fillStyle = 'rgba(255,255,255,0.92)';
    uctx.fillRect(0, 0, UW, UH);

    // 標題
    const winScale = 1 + 0.1 * Math.sin(ts / 300);
    uctx.save();
    uctx.translate(UW / 2, 200);
    uctx.scale(winScale, winScale);
    uctx.fillStyle = '#ffd43b';
    uctx.font = 'bold 88px sans-serif';
    uctx.textAlign = 'center';
    uctx.textBaseline = 'middle';
    uctx.shadowColor = 'rgba(0,0,0,0.15)';
    uctx.shadowBlur = 30;
    uctx.fillText('🎉 ' + uName(U.winner) + ' 獲勝！', 0, 0);
    uctx.restore();

    // ===== 累計勝場榜（中央面板） =====
    const rankW = 700, rankX = UW / 2 - rankW / 2, rankY = 320;
    const rankH = 120 + U.order.length * 76;
    drawSoftPanel(uctx, rankX, rankY, rankW, rankH, 32, '#fffbf0', true);
    uctx.strokeStyle = '#ffe8cc';
    uctx.lineWidth = 4;
    roundRectPath(uctx, rankX, rankY, rankW, rankH, 32);
    uctx.stroke();

    // 標題
    uctx.fillStyle = THEME.text;
    uctx.font = 'bold 40px sans-serif';
    uctx.textAlign = 'center';
    uctx.textBaseline = 'middle';
    uctx.fillText('🏆 累計勝場', UW / 2, rankY + 60);

    // 依累計勝場排序（同分時依剩餘手牌）
    const scoreRank = U.order.slice().sort(function (a, b) {
      const sa = U.scores[a] || 0, sb = U.scores[b] || 0;
      if (sa !== sb) return sb - sa;
      return U.hands[a].length - U.hands[b].length;
    });

    uctx.font = '36px sans-serif';
    for (let i = 0; i < scoreRank.length; i++) {
      const pid = scoreRank[i];
      const isWin = pid === U.winner;
      const wins = U.scores[pid] || 0;
      const y = rankY + 130 + i * 76;

      // 勝者高亮背景
      if (isWin) {
        uctx.fillStyle = 'rgba(255,212,59,0.25)';
        roundRectPath(uctx, rankX + 20, y - 28, rankW - 40, 60, 16);
        uctx.fill();
      }

      // 玩家色點
      uctx.fillStyle = U.colors[pid] || '#adb5bd';
      uctx.beginPath();
      uctx.arc(rankX + 60, y, 16, 0, Math.PI * 2);
      uctx.fill();
      uctx.lineWidth = 3;
      uctx.strokeStyle = '#fff';
      uctx.stroke();

      // 名次
      uctx.fillStyle = isWin ? '#e8590c' : THEME.text;
      uctx.font = 'bold 36px sans-serif';
      uctx.textAlign = 'left';
      const medal = ['🥇', '🥈', '🥉'][i] || (i + 1) + '.';
      uctx.fillText(medal, rankX + 92, y + 2);

      // 名字
      uctx.fillText(uName(pid), rankX + 160, y + 2);

      // 勝場（右側大字）
      uctx.fillStyle = isWin ? '#e8590c' : THEME.textLight;
      uctx.font = 'bold 44px sans-serif';
      uctx.textAlign = 'right';
      uctx.fillText(wins + ' 勝', rankX + rankW - 50, y + 2);

      // 本局剩牌（小字）
      uctx.fillStyle = THEME.textLight;
      uctx.font = '24px sans-serif';
      uctx.fillText('（剩 ' + U.hands[pid].length + ' 張）', rankX + rankW - 50, y + 32);
    }

    // 下一局倒數（logic 端 rematchAt 排程；主持人隨時可推進到結果結束整場）
    if (U.rematchAt) {
      const leftS = Math.max(0, Math.ceil((U.rematchAt - performance.now()) / 1000));
      uctx.fillStyle = '#e8590c';
      uctx.font = 'bold 44px sans-serif';
      uctx.textAlign = 'center';
      uctx.fillText('🔄 ' + leftS + ' 秒後自動開始第 ' + (U.round + 1) + ' 局', UW / 2, UH - 130);
    }
    uctx.fillStyle = THEME.textLight;
    uctx.font = '32px sans-serif';
    uctx.textAlign = 'center';
    uctx.fillText('主持人推進到結果階段即結束整場（依累計勝場排名）', UW / 2, UH - 70);
  }
}

GameAPI.update(function (ts) {
  uTick();
  uRender(ts);
});

// ===== UNO 手機端：明亮卡通風（720×1280 直式） =====
try { GameAPI.log('APIKEYS:' + Object.keys(GameAPI).join(',')); } catch (e) {}
const MW = GameAPI.width, MH = GameAPI.height;
const mctx = GameAPI.ctx;
const myId = GameAPI.playerId;
const myName = GameAPI.playerName || '我';

let S = null;             // 最新遊戲狀態
let pendingWild = null;   // 點了萬用牌等選色
let handRects = [];       // 手牌點擊區
let btnRects = {};        // 按鈕點擊區
let pickerRects = [];     // 選色區
let lastHello = 0;

// 動畫狀態
const mAnim = {
  cardScales: {},       // cardId -> 點擊縮放
  cardLift: {},         // cardId -> 上抬量（動畫）
  banner: 0,            // 頂部橫幅脈動
  lastHandCount: 0,
  dealAnim: 0,          // 發牌動畫進度
};

// 音效初始化（需 user gesture）
let soundReady = false;
function mInitSound() {
  if (!soundReady) {
    USound.init();
    soundReady = true;
  }
}

GameAPI.sendEvent({ t: 'hello' });

GameAPI.onMessage(function (msg) {
  if (msg && msg.t === 'state') {
    const prevPhase = S ? S.phase : null;
    const prevHand = S && S.hands[myId] ? S.hands[myId].length : 0;
    S = msg;
    const nowHand = S.hands[myId] ? S.hands[myId].length : 0;

    // 發牌/抽牌動畫觸發
    if (nowHand > prevHand) {
      mAnim.dealAnim = performance.now();
      if (soundReady) USound.draw();
    }
    // 勝利音效
    if (S.phase === 'over' && prevPhase !== 'over' && soundReady) {
      if (S.winner === myId) USound.win();
    }
    // （分數寫回框架由 display 端的 uReportScores 負責 — 手機 sendEvent 不在框架攔截範圍，防自報分數）
    // UNO 警告震動
    if (S.unoWindow && S.unoWindow.pid === myId && navigator.vibrate) {
      navigator.vibrate(200);
    }
    // 清理選色狀態
    if (S.phase !== 'colorPick' && pendingWild) {
      if (!(S.hands[myId] || []).some(function (c) { return c.id === pendingWild; })) {
        pendingWild = null;
      }
    }
  }
});

function mMyTurn() { return S && S.cur === myId && S.phase !== 'over'; }
function mInGame() { return S && S.order.some(function (o) { return o.pid === myId; }); }

function mSendPlay(cardId, color) {
  mInitSound();
  USound.card();
  GameAPI.sendEvent({ t: 'play', cardId: cardId, color: color || null });
}

// ---------- 輸入 ----------
GameAPI.canvas.addEventListener('pointerdown', function (e) {
  mInitSound();
  const rect = GameAPI.canvas.getBoundingClientRect();
  const x = (e.clientX - rect.left) / rect.width * MW;
  const y = (e.clientY - rect.top) / rect.height * MH;
  if (!S) return;

  // 選色覆蓋層最優先
  if (pickerRects.length) {
    for (const p of pickerRects) {
      if (x >= p.x && x <= p.x + p.w && y >= p.y && y <= p.y + p.h) {
        USound.card();
        if (pendingWild) {
          mSendPlay(pendingWild, p.color);
          pendingWild = null;
        } else {
          GameAPI.sendEvent({ t: 'color', color: p.color });
        }
        return;
      }
    }
    return;
  }

  // 按鈕
  for (const key of Object.keys(btnRects)) {
    const b = btnRects[key];
    if (b.enabled && x >= b.x && x <= b.x + b.w && y >= b.y && y <= b.y + b.h) {
      if (key === 'draw') { USound.draw(); GameAPI.sendEvent({ t: 'draw' }); }
      else if (key === 'pass') { USound.card(); GameAPI.sendEvent({ t: 'pass' }); }
      else if (key === 'uno') { USound.uno(); GameAPI.sendEvent({ t: 'uno' }); }
      return;
    }
  }

  // 手牌
  if (!mMyTurn()) return;
  const hand = S.hands[myId] || [];
  for (let i = handRects.length - 1; i >= 0; i--) {
    const r = handRects[i];
    if (x >= r.x && x <= r.x + r.w && y >= r.y && y <= r.y + r.h) {
      const card = hand[i];
      // 點擊動畫
      mAnim.cardScales[card.id] = performance.now();

      if (S.phase === 'drawn') {
        if (card.id === S.drawnId) mSendPlay(card.id);
        else USound.error();
        return;
      }
      if (S.phase !== 'playing') return;
      if (!unoCanPlay(card, S.top, S.color, hand)) { USound.error(); return; }
      if (card.color === 'W') pendingWild = card.id;
      else mSendPlay(card.id);
      return;
    }
  }
});

// ---------- 手牌扇形佈局 ----------
function mFanLayout(n) {
  const cx = MW / 2, cy = 880; // 扇形中心（畫面下方）
  const maxSpread = Math.min(500, n * 60); // 總展開寬度
  const cardW = Math.min(140, Math.max(90, 600 / Math.max(1, n - 1)));
  const cardH = cardW * 1.42;

  const rects = [];
  for (let i = 0; i < n; i++) {
    const t = n === 1 ? 0.5 : i / (n - 1);
    const spread = (t - 0.5) * maxSpread;
    const x = cx + spread - cardW / 2;
    // 中間的牌稍微上抬（拱形）
    const arch = Math.sin(t * Math.PI) * 30;
    const y = cy - arch;
    // 旋轉角度（扇形感）
    const rot = (t - 0.5) * 0.3;
    rects.push({ x, y, w: cardW, h: cardH, rot, cx: x + cardW / 2, cy: y + cardH / 2 });
  }
  return rects;
}

// ---------- 按鈕 ----------
function mDrawBtn(key, x, y, w, h, label, enabled, color, ts) {
  btnRects[key] = { x, y, w, h, enabled };
  mctx.save();

  if (enabled) {
    // 陰影
    mctx.shadowColor = 'rgba(0,0,0,0.2)';
    mctx.shadowBlur = 12;
    mctx.shadowOffsetY = 4;

    // 漸層
    const g = mctx.createLinearGradient(x, y, x, y + h);
    g.addColorStop(0, color);
    g.addColorStop(1, shadeColor(color, -20));
    mctx.fillStyle = g;
  } else {
    mctx.fillStyle = 'rgba(255,255,255,0.2)';
  }

  // 膠囊形
  roundRectPath(mctx, x, y, w, h, h / 2);
  mctx.fill();
  mctx.restore();

  // UNO 按鈕脈動
  if (key === 'uno' && enabled) {
    const pulse = 0.9 + 0.1 * Math.sin(ts / 200);
    mctx.save();
    mctx.strokeStyle = 'rgba(255,107,107,' + (0.5 + 0.5 * Math.sin(ts / 200)) + ')';
    mctx.lineWidth = 4;
    roundRectPath(mctx, x - 4, y - 4, w + 8, h + 8, (h + 8) / 2);
    mctx.stroke();
    mctx.restore();
  }

  mctx.fillStyle = enabled ? '#fff' : 'rgba(255,255,255,0.4)';
  mctx.font = 'bold ' + Math.floor(h * 0.4) + 'px sans-serif';
  mctx.textAlign = 'center';
  mctx.textBaseline = 'middle';
  mctx.fillText(label, x + w / 2, y + h / 2 + 2);
}

function shadeColor(hex, percent) {
  const num = parseInt(hex.replace('#', ''), 16);
  const amt = Math.round(2.55 * percent);
  const R = Math.min(255, Math.max(0, (num >> 16) + amt));
  const G = Math.min(255, Math.max(0, (num >> 8 & 0xff) + amt));
  const B = Math.min(255, Math.max(0, (num & 0xff) + amt));
  return '#' + (0x1000000 + R * 0x10000 + G * 0x100 + B).toString(16).slice(1);
}

// ---------- 主渲染 ----------
function mRender(ts) {
  btnRects = {};
  pickerRects = [];
  handRects = [];

  // 背景：柔和漸層
  const g = mctx.createLinearGradient(0, 0, 0, MH);
  g.addColorStop(0, '#e7f5ff');
  g.addColorStop(0.5, '#fff9db');
  g.addColorStop(1, '#ffe8cc');
  mctx.fillStyle = g;
  mctx.fillRect(0, 0, MW, MH);

  // 裝飾圓
  mctx.fillStyle = 'rgba(255,255,255,0.5)';
  for (let i = 0; i < 4; i++) {
    const a = ts / 4000 + i * Math.PI / 2;
    mctx.beginPath();
    mctx.arc(MW / 2 + Math.cos(a) * 200, 300 + i * 200, 150 + i * 50, 0, Math.PI * 2);
    mctx.fill();
  }

  if (!S) {
    mctx.fillStyle = '#343a40';
    mctx.font = 'bold 64px sans-serif';
    mctx.textAlign = 'center';
    mctx.textBaseline = 'middle';
    mctx.fillText('UNO', MW / 2, MH / 2 - 60);
    mctx.font = '32px sans-serif';
    mctx.fillStyle = '#868e96';
    mctx.fillText('連線中…', MW / 2, MH / 2 + 40);
    return;
  }

  if (!mInGame()) {
    mctx.fillStyle = '#343a40';
    mctx.font = 'bold 48px sans-serif';
    mctx.textAlign = 'center';
    mctx.textBaseline = 'middle';
    mctx.fillText('本局已開始', MW / 2, MH / 2 - 40);
    mctx.font = '32px sans-serif';
    mctx.fillStyle = '#868e96';
    mctx.fillText('觀戰中，下一局見！', MW / 2, MH / 2 + 30);
    return;
  }

  const hand = S.hands[myId] || [];
  const myTurn = mMyTurn();
  const now = performance.now();

  // ===== 頂部資訊面板 =====
  drawSoftPanel(mctx, 20, 20, MW - 40, 180, 24, 'rgba(255,255,255,0.85)', true);

  // 標題
  mctx.fillStyle = '#343a40';
  mctx.font = 'bold 44px sans-serif';
  mctx.textAlign = 'left';
  mctx.textBaseline = 'middle';
  mctx.fillText('UNO', 44, 60);

  // 我的累計勝場
  const myWins = (S.scores && S.scores[myId]) || 0;
  if (myWins > 0) {
    mctx.fillStyle = '#ffd43b';
    mctx.beginPath();
    mctx.arc(44 + 60, 60, 22, 0, Math.PI * 2);
    mctx.fill();
    mctx.lineWidth = 2;
    mctx.strokeStyle = '#fff';
    mctx.stroke();
    mctx.fillStyle = '#fff';
    mctx.font = 'bold 26px sans-serif';
    mctx.textAlign = 'center';
    mctx.fillText(myWins, 44 + 60, 62);
  }

  // 方向 + 牌庫
  mctx.font = '28px sans-serif';
  mctx.fillStyle = '#868e96';
  mctx.fillText((S.dir === 1 ? '⟳ 順時針' : '⟲ 逆時針') + ' · 牌庫 ' + S.deckCount, 44, 110);

  // 桌面頂牌（右上角）
  if (S.top) {
    drawUnoCard(mctx, S.top, MW - 140, 36, 96, 136, {
      chosenColor: S.top.color === 'W' ? S.color : null,
    });
    // 指定色圓點
    const ci = UNO_COLOR_INFO[S.color];
    mctx.fillStyle = ci.hex;
    mctx.beginPath();
    mctx.arc(MW - 160, 60, 22, 0, Math.PI * 2);
    mctx.fill();
    mctx.lineWidth = 3;
    mctx.strokeStyle = '#fff';
    mctx.stroke();
  }

  // 回合提示（脈動）
  mctx.textAlign = 'center';
  mctx.font = 'bold 36px sans-serif';
  if (S.phase === 'over') {
    mctx.fillStyle = '#e8590c';
    mctx.fillText('牌局結束', MW / 2, 170);
  } else if (myTurn) {
    const pulse = 0.7 + 0.3 * Math.sin(ts / 300);
    mctx.fillStyle = 'rgba(230,89,12,' + pulse + ')';
    mctx.fillText('✨ 你的回合！', MW / 2, 170);
  } else {
    mctx.fillStyle = '#868e96';
    const cur = S.order.find(function (o) { return o.pid === S.cur; });
    mctx.fillText('等待 ' + (cur ? cur.name : '對手') + '…', MW / 2, 170);
  }

  // ===== 對手列 =====
  const others = S.order.filter(function (o) { return o.pid !== myId; });
  const chipW = Math.min(150, (MW - 60 - (others.length - 1) * 12) / Math.max(1, others.length));
  others.forEach(function (o, i) {
    const x = 30 + i * (chipW + 12);
    const y = 220;
    const isCur = o.pid === S.cur && S.phase !== 'over';

    // 面板
    drawSoftPanel(mctx, x, y, chipW, 100, 20,
      isCur ? 'rgba(255,243,191,0.95)' : 'rgba(255,255,255,0.7)', isCur);

    if (isCur) {
      mctx.strokeStyle = '#ffd43b';
      mctx.lineWidth = 3;
      roundRectPath(mctx, x, y, chipW, 100, 20);
      mctx.stroke();
    }

    // 名字
    mctx.fillStyle = '#343a40';
    mctx.font = 'bold 24px sans-serif';
    mctx.textAlign = 'center';
    mctx.textBaseline = 'middle';
    const nm = o.name.length > 4 ? o.name.slice(0, 4) + '…' : o.name;
    mctx.fillText(nm, x + chipW / 2, y + 32);

    // 牌數
    mctx.fillStyle = o.count === 1 ? '#e8590c' : '#868e96';
    mctx.font = '26px sans-serif';
    mctx.fillText('🂠 ' + o.count, x + chipW / 2, y + 70);
  });

  // ===== 提示橫幅 =====
  if (myTurn && S.phase === 'drawn') {
    const bounce = Math.sin(ts / 200) * 4;
    drawSoftPanel(mctx, 40, 340 + bounce, MW - 80, 56, 28, 'rgba(255,243,191,0.95)', false);
    mctx.fillStyle = '#e8590c';
    mctx.font = 'bold 28px sans-serif';
    mctx.textAlign = 'center';
    mctx.fillText('抽到可出的牌！點它或按「跳過」', MW / 2, 370 + bounce);
  }

  // ===== 手牌（扇形展開） =====
  const fanRects = mFanLayout(hand.length);
  for (let i = 0; i < hand.length; i++) {
    const card = hand[i];
    const r = fanRects[i];
    handRects.push({ x: r.x, y: r.y, w: r.w, h: r.h });

    let playable = false;
    if (myTurn) {
      if (S.phase === 'drawn') playable = card.id === S.drawnId;
      else if (S.phase === 'playing') playable = unoCanPlay(card, S.top, S.color, hand);
    }

    // 點擊縮放動畫
    let scale = 1;
    if (mAnim.cardScales[card.id]) {
      const age = now - mAnim.cardScales[card.id];
      if (age < 200) {
        scale = 0.92 + 0.08 * (age / 200);
      } else {
        delete mAnim.cardScales[card.id];
      }
    }

    // 可出牌上抬
    const lift = playable ? 24 : 0;

    mctx.save();
    mctx.translate(r.cx, r.cy);
    mctx.rotate(r.rot);
    mctx.scale(scale, scale);
    drawUnoCard(mctx, card, -r.w / 2, -r.h / 2 - lift, r.w, r.h, {
      dim: !playable && myTurn,
      glow: playable,
      chosenColor: card.color === 'W' && S.top && S.top.id === card.id ? S.color : null,
    });
    mctx.restore();
  }

  if (hand.length === 0 && S.phase !== 'over') {
    mctx.fillStyle = '#868e96';
    mctx.font = '32px sans-serif';
    mctx.textAlign = 'center';
    mctx.fillText('（沒有手牌）', MW / 2, 900);
  }

  // ===== 底部按鈕 =====
  const bw = 200, bh = 88, by = 1080, gap = 20;
  const bx0 = (MW - (bw * 3 + gap * 2)) / 2;
  const canAct = myTurn && S.phase === 'playing';
  const canPass = myTurn && S.phase === 'drawn';
  const unoHot = (S.unoWindow && S.unoWindow.pid === myId) || (myTurn && hand.length === 2);

  mDrawBtn('draw', bx0, by, bw, bh, '抽牌', canAct, '#339af0', ts);
  mDrawBtn('uno', bx0 + bw + gap, by, bw, bh, 'UNO!', unoHot, '#ff6b6b', ts);
  mDrawBtn('pass', bx0 + (bw + gap) * 2, by, bw, bh, '跳過', canPass, '#868e96', ts);

  // ===== UNO 警告 =====
  if (S.unoWindow && S.unoWindow.pid === myId) {
    const pulse = 0.8 + 0.2 * Math.sin(ts / 150);
    mctx.save();
    mctx.globalAlpha = pulse;
    drawSoftPanel(mctx, 60, 1190, MW - 120, 80, 40, '#ff6b6b', true);
    mctx.fillStyle = '#fff';
    mctx.font = 'bold 36px sans-serif';
    mctx.textAlign = 'center';
    mctx.fillText('⚠️ 快按 UNO！否則罰抽 2 張', MW / 2, 1232);
    mctx.restore();
  }

  // ===== 選色覆蓋層 =====
  if (pendingWild || (myTurn && S.phase === 'colorPick')) {
    mctx.fillStyle = 'rgba(255,255,255,0.92)';
    mctx.fillRect(0, 0, MW, MH);

    mctx.fillStyle = '#343a40';
    mctx.font = 'bold 48px sans-serif';
    mctx.textAlign = 'center';
    mctx.textBaseline = 'middle';
    mctx.fillText('🎨 指定顏色', MW / 2, 380);

    const size = 260, pgap = 40;
    const px0 = (MW - size * 2 - pgap) / 2, py0 = 460;
    UNO_COLORS.forEach(function (c, i) {
      const x = px0 + (i % 2) * (size + pgap);
      const y = py0 + Math.floor(i / 2) * (size + pgap);
      pickerRects.push({ x, y, w: size, h: size, color: c });

      const ci = UNO_COLOR_INFO[c];
      // 漸層按鈕
      const g2 = mctx.createLinearGradient(x, y, x + size, y + size);
      g2.addColorStop(0, ci.light);
      g2.addColorStop(1, ci.hex);
      mctx.fillStyle = g2;
      mctx.save();
      mctx.shadowColor = 'rgba(0,0,0,0.2)';
      mctx.shadowBlur = 16;
      mctx.shadowOffsetY = 6;
      roundRectPath(mctx, x, y, size, size, 40);
      mctx.fill();
      mctx.restore();

      mctx.fillStyle = '#fff';
      mctx.font = 'bold 64px sans-serif';
      mctx.textAlign = 'center';
      mctx.textBaseline = 'middle';
      mctx.fillText(ci.name, x + size / 2, y + size / 2);
    });
  }

  // ===== 勝利覆蓋層 =====
  if (S.phase === 'over') {
    mctx.fillStyle = 'rgba(255,255,255,0.96)';
    mctx.fillRect(0, 0, MW, MH);

    const winName = (S.order.find(function (o) { return o.pid === S.winner; }) || {}).name || '';
    const isMe = S.winner === myId;

    // 彈跳標題
    const bounce = Math.sin(ts / 300) * 10;
    mctx.fillStyle = isMe ? '#ffd43b' : '#868e96';
    mctx.font = 'bold 64px sans-serif';
    mctx.textAlign = 'center';
    mctx.textBaseline = 'middle';
    mctx.save();
    mctx.shadowColor = 'rgba(0,0,0,0.15)';
    mctx.shadowBlur = 20;
    mctx.fillText(isMe ? '🎉 你贏了！' : winName + ' 獲勝', MW / 2, 200 + bounce);
    mctx.restore();

    // 累計勝場榜
    drawSoftPanel(mctx, 40, 320, MW - 80, 120 + S.order.length * 68, 24, '#fffbf0', true);
    mctx.strokeStyle = '#ffe8cc';
    mctx.lineWidth = 3;
    roundRectPath(mctx, 40, 320, MW - 80, 120 + S.order.length * 68, 24);
    mctx.stroke();

    mctx.fillStyle = '#343a40';
    mctx.font = 'bold 36px sans-serif';
    mctx.textAlign = 'center';
    mctx.fillText('🏆 累計勝場', MW / 2, 370);

    const scoreRank = S.order.slice().sort(function (a, b) {
      const sa = (S.scores && S.scores[a.pid]) || 0;
      const sb = (S.scores && S.scores[b.pid]) || 0;
      if (sa !== sb) return sb - sa;
      return a.count - b.count;
    });

    mctx.font = '30px sans-serif';
    for (let i = 0; i < scoreRank.length; i++) {
      const o = scoreRank[i];
      const isWinner = o.pid === S.winner;
      const isSelf = o.pid === myId;
      const wins = (S.scores && S.scores[o.pid]) || 0;
      const y = 430 + i * 68;

      if (isWinner) {
        mctx.fillStyle = 'rgba(255,212,59,0.3)';
        roundRectPath(mctx, 60, y - 24, MW - 120, 52, 14);
        mctx.fill();
      }

      mctx.fillStyle = isWinner ? '#e8590c' : (isSelf ? '#339af0' : '#343a40');
      mctx.font = 'bold 30px sans-serif';
      mctx.textAlign = 'left';
      const medal = ['🥇', '🥈', '🥉'][i] || (i + 1) + '.';
      mctx.fillText(medal + ' ' + o.name + (isSelf ? '（你）' : ''), 80, y);

      mctx.textAlign = 'right';
      mctx.font = 'bold 34px sans-serif';
      mctx.fillText(wins + ' 勝', MW - 80, y);
    }

    // 下一局倒數（state 的 rematchLeftMs 由 display 廣播；心跳 1 秒一次，粗粒度即可）
    if (S.rematchLeftMs != null) {
      const leftS = Math.max(0, Math.ceil(S.rematchLeftMs / 1000));
      mctx.fillStyle = '#e8590c';
      mctx.font = 'bold 34px sans-serif';
      mctx.textAlign = 'center';
      mctx.fillText('🔄 ' + leftS + ' 秒後自動開始下一局', MW / 2, MH - 120);
    }
    mctx.fillStyle = '#868e96';
    mctx.font = '28px sans-serif';
    mctx.textAlign = 'center';
    mctx.fillText('主持人結束整場後依累計勝場排名', MW / 2, MH - 70);
  }
}

GameAPI.update(function (ts) {
  if (!S && ts - lastHello > 2000) {
    lastHello = ts;
    GameAPI.sendEvent({ t: 'hello' });
  }
  mRender(ts);
});
